files.campaigns/TheBunker/npcs/dialogues/greet:
{
	"conversations": [
		{
			"id": "greeter_intro",
			"trigger_conditions": {
				"flags_required": [],
				"flags_excluded": [
					"met_greeter"
				],
				"faction_rep": {}
			},
			"entry_node": "gr_in_001",
			"nodes": {
				"gr_in_001": {
					"type": "npc_line",
					"speaker": "greeter",
					"text": "Haven't seen you before. I'm Mara — I keep an eye on the square. (This whole conversation is an example. Open npcs/dialogues/greeter.json to see how it's built.)",
					"next": "gr_in_choice"
				},
				"gr_in_choice": {
					"type": "player_choice",
					"choices": [
						{
							"id": "c_help",
							"text": "Anything I can do around here?",
							"condition": null,
							"next": "gr_in_quest"
						},
						{
							"id": "c_charm",
							"text": "[Speech 40] You look like you could use a friend.",
							"condition": {
								"type": "skill_check",
								"skill": "speech",
								"difficulty": 40,
								"on_fail": "gr_in_charm_fail"
							},
							"next": "gr_in_charm_pass"
						},
						{
							"id": "c_leave",
							"text": "Just passing through.",
							"condition": null,
							"next": null
						}
					]
				},
				"gr_in_quest": {
					"type": "npc_line",
					"speaker": "greeter",
					"text": "There's a supply crate by the east wall — was meant for the fountain repair. Crack it open and bring me what's inside, would you?",
					"next": "gr_in_choice"
				},
				"gr_in_charm_pass": {
					"type": "npc_line",
					"speaker": "greeter",
					"text": "Heh. Smooth. All right, stranger — you've got a friend in the square.",
					"flags_set": [
						"greeter_likes_you"
					],
					"relationship_change": 1,
					"karma_change": 2,
					"next": "gr_in_choice"
				},
				"gr_in_charm_fail": {
					"type": "npc_line",
					"speaker": "greeter",
					"text": "...Sure. Let's not get ahead of ourselves.",
					"next": "gr_in_choice"
				}
			},
			"on_complete": {
				"flags_set": [
					"met_greeter"
				],
				"relationship_change": 1,
				"quests_started": [
					"first_steps"
				]
			}
		},
		{
			"id": "greeter_returning",
			"trigger_conditions": {
				"flags_required": [
					"met_greeter"
				],
				"flags_excluded": [],
				"faction_rep": {}
			},
			"entry_node": "gr_ret_001",
			"nodes": {
				"gr_ret_001": {
					"type": "npc_line",
					"speaker": "greeter",
					"text": "Back again. The square's quiet today.",
					"next": "gr_ret_choice"
				},
				"gr_ret_choice": {
					"type": "player_choice",
					"choices": [
						{
							"id": "c_turnin",
							"text": "I opened that crate — here's what was inside.",
							"condition": {
								"type": "flag_required",
								"flag": "template_crate_opened"
							},
							"next": "gr_ret_thanks"
						},
						{
							"id": "c_bye",
							"text": "Just saying hello.",
							"condition": null,
							"next": null
						}
					]
				},
				"gr_ret_thanks": {
					"type": "npc_line",
					"speaker": "greeter",
					"text": "Bless you. The fountain'll run again yet. Here — take this for your trouble.",
					"flags_set": [
						"first_steps_turned_in"
					],
					"caps_reward": 30,
					"xp_reward": 50,
					"relationship_change": 2,
					"next": null
				}
			},
			"on_complete": {
				"flags_set": []
			}
		}
	]
}

