{
	"id": "first_steps",
	"title": "First Steps",
	"summary": "Mara asked you to open the supply crate by the east wall and bring her what's inside.",
	"xp_reward": 50,
	"caps_reward": 0,
	"karma_reward": 2,
	"item_rewards": [],
	"ends_game": true,
	"stages": [
		{
			"id": "stage_open",
			"title": "Open the supply crate",
			"description": "Find the supply crate in the town square and open it.",
			"objectives": [
				{
					"id": "obj_open_crate",
					"text": "Open the supply crate",
					"flag_complete": "template_crate_opened",
					"optional": false
				}
			],
			"completion_condition": {
				"flags_all": [
					"template_crate_opened"
				]
			},
			"on_complete": {
				"flags_set": [],
				"next_stage": "stage_return"
			}
		},
		{
			"id": "stage_return",
			"title": "Report back to Mara",
			"description": "Bring what you found back to Mara.",
			"objectives": [
				{
					"id": "obj_return",
					"text": "Tell Mara you opened the crate",
					"flag_complete": "first_steps_turned_in",
					"optional": false
				}
			],
			"completion_condition": {
				"flags_all": [
					"first_steps_turned_in"
				]
			},
			"on_complete": {
				"flags_set": [
					"first_steps_complete"
				],
				"next_stage": null
			}
		}
	]
}

